$$
\begin{aligned}
&\begin{aligned}
& \mathrm{mg}-\mathrm{F} \sin 30^{\circ}=\mathrm{N} \\
& \mathrm{f}=\mu(\mathrm{N}) \quad=\mu\left(\mathrm{mg}-\mathrm{F} \sin 30^{\circ}\right) \\
& \mu=0.25 \text { given }
\end{aligned}\\
&\text { To start motion , F } \cos 30^{\circ} \geq \mu \mathrm{N}\\
&\begin{aligned}
& \mathrm{F} \cos 30^{\circ} \geq \mu\left(\mathrm{mg}-\mathrm{F} \sin 30^{\circ}\right) \\
& \mathrm{F} \frac{\sqrt{3}}{2} \geq \frac{1}{4}\left(100-\mathrm{F} \frac{1}{2}\right) \quad \mathrm{F} \frac{\sqrt{3}}{2}+\mathrm{F} \frac{1}{8} \geq \frac{100}{4} \\
& \mathrm{~F}\left(\frac{4 \sqrt{3}+1}{8}\right) \geq 25, \mathrm{~F}=\frac{25 \times 8}{4 \sqrt{3}+1}=25.2 \mathrm{~N}
\end{aligned}
\end{aligned}
$$
